<script setup lang="ts">
import { UiButton, UiInput } from '@/ui/base'
import { computed } from 'vue'
import { useI18n } from 'vue-i18n'
import type { Member } from '@/types/enterprise'
import { useEnterpriseStore } from '@/stores/enterprise'
import AvatarMark from '@/ui/common/AvatarMark.vue'
import StatusBadge from '@/ui/common/StatusBadge.vue'
import AppIcon from '@/ui/common/AppIcon.vue'
import MemberRoleTags from './MemberRoleTags.vue'
export type MemberSortKey='name'|'departmentId'|'status'|'lastLogin'|'joinedAt'
const props=defineProps<{members:Member[];selected:string[];detailId?:string|null;sortKey?:MemberSortKey;sortDirection?:'asc'|'desc';sortable?:boolean;canEdit?:boolean;canMore?:boolean}>()
const emit=defineEmits<{'update:selected':[ids:string[]];detail:[member:Member];edit:[member:Member];more:[member:Member];sort:[key:MemberSortKey]}>(),store=useEnterpriseStore(),{t}=useI18n()
const allSelected=computed(()=>props.members.length>0&&props.members.every(m=>props.selected.includes(m.id)))
const columns=computed(()=>[
  {label:t('members.columns.name'),key:'name' as MemberSortKey,className:'name-column'},
  {label:t('members.columns.contact'),className:'contact-column'},
  {label:t('members.columns.department'),key:'departmentId' as MemberSortKey,className:'department-column'},
  {label:t('members.columns.role'),className:'role-column'},
  {label:t('members.columns.scope'),className:'scope-column'},
  {label:t('members.columns.status'),key:'status' as MemberSortKey,className:'status-column'},
  {label:t('members.columns.lastLogin'),key:'lastLogin' as MemberSortKey,className:'login-column'},
  {label:t('members.columns.joinedAt'),key:'joinedAt' as MemberSortKey,className:'joined-column'},
  {label:t('members.columns.actions'),className:'actions-column'}
])
const scopeLabel=(scope:Member['scope'])=>t(`members.scopes.${scope==='department_tree'?'department':scope==='self'?'own':scope}`)
const statusLabel=(status:Member['status'])=>t(`members.statuses.${status}`)
function toggle(id:string){emit('update:selected',props.selected.includes(id)?props.selected.filter(i=>i!==id):[...props.selected,id])}
</script>
<template>
  <div class="table-scroll member-table-scroll" tabindex="0" :aria-label="t('members.tableScroll')"><table class="data-table member-table"><colgroup><col class="check-column"/><col v-for="column in columns" :key="column.label" :class="column.className"/></colgroup><thead><tr><th class="check-cell"><UiInput type="checkbox" :aria-label="t('members.selectPage')" :checked="allSelected" :indeterminate="selected.length>0&&!allSelected" @change="emit('update:selected',allSelected?[]:members.map(m=>m.id))"/></th><th v-for="column in columns" :key="column.label" :class="column.className" :aria-sort="column.key===sortKey?(sortDirection==='desc'?'descending':'ascending'):undefined"><UiButton v-if="column.key&&sortable!==false" class="column-sort" :aria-label="t('members.sortBy',{column:column.label})" @click="emit('sort',column.key)">{{ column.label }}<span class="sort-indicator" :class="{sorted:column.key===sortKey}" aria-hidden="true"><AppIcon name="down" :size="10" :class="{ascending:column.key===sortKey&&sortDirection!=='desc'}"/></span></UiButton><template v-else>{{ column.label }}</template></th></tr></thead><tbody><tr v-for="member in members" :key="member.id" :class="{selected:selected.includes(member.id),viewing:detailId===member.id}" :data-member-id="member.id"><td class="check-cell"><UiInput type="checkbox" :aria-label="t('members.selectMember',{name:member.name})" :checked="selected.includes(member.id)" @change="toggle(member.id)"/></td><td><UiButton class="member-identity" :aria-label="t('members.viewProfile',{name:member.name})" @click="emit('detail',member)"><AvatarMark :name="member.name" :size="28" :tone="member.roleIds.includes('owner')?'slate':'solid'"/><span class="identity-copy"><strong :title="member.name">{{ member.name }}</strong><small v-if="member.username" :title="member.username">@{{ member.username }}</small></span></UiButton></td><td class="contact-cell"><span :title="`${member.phone} / ${member.email}`">{{ member.email }}</span></td><td class="department-cell"><span :title="store.departmentName(member.departmentId)">{{ store.departmentName(member.departmentId) }}</span></td><td><MemberRoleTags :ids="member.roleIds"/></td><td class="scope-cell"><span :title="scopeLabel(member.scope)">{{ scopeLabel(member.scope) }}</span></td><td><StatusBadge :text="statusLabel(member.status)" :tone="member.status==='active'?'success':member.status==='invited'?'warning':member.status==='suspended'?'danger':'neutral'"/></td><td class="muted numeric time-cell">{{ member.lastLogin||t('members.neverLoggedIn') }}</td><td class="muted numeric time-cell">{{ member.joinedAt }}</td><td class="actions-column"><div class="table-actions"><UiButton class="btn-link" :aria-label="t('members.viewMember',{name:member.name})" :aria-expanded="detailId===member.id" aria-controls="member-detail-panel" @click="emit('detail',member)">{{ t('common.view') }}</UiButton><UiButton v-if="canEdit" class="btn-link" :aria-label="t('members.editMember',{name:member.name})" @click="emit('edit',member)">{{ t('common.edit') }}</UiButton><UiButton v-if="canMore" class="icon-button" :aria-label="t('members.moreActions',{name:member.name})" @click="emit('more',member)"><AppIcon name="more" :size="17"/></UiButton></div></td></tr></tbody></table></div>
</template>
<style scoped>
.member-table{min-width:900px;table-layout:fixed;font-size:12px}.check-column{width:30px}.name-column{width:100px}.department-column{width:100px}.role-column{width:100px}.scope-column{width:110px}.status-column{width:82px}.login-column{width:120px}.joined-column{width:90px}.actions-column{width:105px}.member-table th{height:40px;padding:0 6px;font-size:11px}.member-table td{height:min(46px,var(--table-row-height));padding:6px}.member-table .check-cell{padding-left:8px;padding-right:0}.member-identity{display:flex;align-items:center;gap:8px;text-align:left;padding:0;width:100%}.identity-copy{display:grid;min-width:0}.member-identity strong{overflow:hidden;text-overflow:ellipsis;font-size:12px;font-weight:550}.identity-copy small{overflow:hidden;text-overflow:ellipsis;color:var(--color-text-muted);font-size:10px}.member-identity:hover strong{color:var(--color-primary)}.contact-cell span,.department-cell span,.scope-cell span{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.contact-cell{color:var(--color-text-secondary);font-size:11px}.department-cell,.scope-cell{font-size:11px}.time-cell{font-size:10.5px;letter-spacing:-.1px}.member-table :deep(.status-badge){font-size:11px;padding:2px 5px}.table-actions{gap:5px}.table-actions .btn-link{font-size:11px;padding:3px 0}.table-actions .icon-button{width:22px;height:28px;color:var(--color-primary)}.column-sort{display:flex;align-items:center;gap:4px;padding:0;font-size:inherit;text-align:left}.sort-indicator{color:var(--color-text-muted)}.sort-indicator.sorted{color:var(--color-primary)}.ascending{transform:rotate(180deg)}.member-table tr.viewing{background:var(--color-primary-soft)}.member-table tr.viewing td:first-child{box-shadow:inset 2px 0 var(--color-primary)}.member-table .actions-column{position:sticky;right:0;background:var(--color-surface)}.member-table th.actions-column{background:var(--color-surface-soft)}.member-table tr.selected .actions-column,.member-table tr.viewing .actions-column{background:var(--color-primary-soft)}.member-table tr:hover:not(.selected):not(.viewing) .actions-column{background:var(--color-surface-soft)}@container member-main (min-width:1120px){.name-column{width:118px}.department-column{width:120px}.role-column{width:126px}.scope-column{width:130px}.status-column{width:100px}.login-column{width:150px}.joined-column{width:110px}.actions-column{width:120px}.member-table th{font-size:12px}.member-table td{height:min(49px,var(--table-row-height))}.time-cell,.contact-cell,.department-cell,.scope-cell{font-size:12px}.table-actions{gap:10px}.table-actions .btn-link{font-size:12px}}
</style>
